import json
import pathlib
import unittest

from lounge_sdk.delivery import DecryptError, decrypt_id_token, decrypt_jwe, open_server_data, open_webhook, verify_id_token
from lounge_sdk.webhook import verify_webhook

# SDK/go/testdata/vectors.json is shared by every SDK (generated by the backend delivery module).
VECTORS = json.loads((pathlib.Path(__file__).resolve().parents[2] / "go" / "testdata" / "vectors.json").read_text(encoding="utf-8"))
ISS, AUD = "https://account.example.com", "vector-app"


class DeliveryVectorTests(unittest.TestCase):
    def test_vectors(self):
        keys = VECTORS["keys"]
        every = [keys["rsa"], keys["ec"], keys["x25519"]]
        for v in VECTORS["vectors"]:
            with self.subTest(v["name"]):
                if v.get("fail"):
                    with self.assertRaises(DecryptError):
                        decrypt_jwe(v["compact"], keys[v["key"]])
                    continue
                plain, _ = decrypt_jwe(v["compact"], keys[v["key"]])
                self.assertEqual(plain.decode(), v["plaintext"])
                self.assertEqual(decrypt_jwe(v["compact"], every)[0], plain)
                if v["kind"] == "id_token":
                    claims = decrypt_id_token(v["compact"], every, VECTORS["signing"], ISS, AUD)
                    self.assertEqual(claims["name"], "旅行者")
                    with self.assertRaises(DecryptError):
                        verify_id_token(v["plaintext"], VECTORS["signing"], ISS, "other-app")
                if v["kind"] == "server":
                    self.assertEqual(open_server_data(v["response"], keys[v["key"]], v["ctx"]), json.loads(v["plaintext"]))
                    with self.assertRaises(DecryptError):
                        open_server_data(v["response"], keys[v["key"]], "server:other:whitelist")
                    with self.assertRaises(DecryptError):
                        open_server_data({"code": 0, "data": {"server": "x"}}, keys[v["key"]])
                if v["kind"] == "webhook":
                    verify_webhook(v["secret"], v["headers"], v["body"].encode(), tolerance=None)
                    doc = open_webhook(v["body"], keys[v["key"]])
                    self.assertEqual(doc["data"]["user"]["nickname"], "旅行者")

    def test_wrong_key(self):
        with self.assertRaises(DecryptError):
            decrypt_jwe(VECTORS["vectors"][0]["compact"], VECTORS["keys"]["ec"])


if __name__ == "__main__":
    unittest.main()
